"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["62745"],{64552(e){e.exports=JSON.parse('{"id":"FIN-1447","slug":"post-merger-integration","term":"Post-Merger Integration","also_known_as":[],"difficulty":"Advanced","definition":"Post-merger integration is the process of combining two companies after a merger or acquisition, bringing together their operations, systems, people and cultures to achieve the expected benefits of the deal.","explanation":["Signing a deal is only the start. The value of most acquisitions depends on how well the businesses are combined afterwards. Post-merger integration covers everything from merging finance and IT systems to aligning products, sales teams, policies and organisational structures.","Key activities include deciding on leadership and organisational structure, combining or rationalising facilities, integrating IT systems, aligning processes and policies, retaining key staff and customers, communicating with employees and delivering the synergies promised when the deal was made.","For example, after two banks merge, they must combine their branch networks, migrate customers to a single banking system, unify products and merge their workforces, often over several years.","Poor integration is one of the most common reasons acquisitions fail to create value. Challenges include cultural clashes, loss of key people, customer disruption, IT problems and management distraction. Companies often set up dedicated integration teams and plan integration well before the deal completes."],"note":"","total":1500,"prev":{"slug":"positive-externality","term":"Positive Externality"},"next":{"slug":"post-money-valuation","term":"Post-Money Valuation"}}')}}]);